from collections import deque

def sliding_window_max(nums, w):
    if not nums or w == 0:
        return []
    dq, out = deque(), []
    for i, n in enumerate(nums):
        while dq and dq[0] <= i - w:
            dq.popleft()
        while dq and nums[dq[-1]] <= n:
            dq.pop()
        dq.append(i)
        if i >= w - 1:
            out.append(nums[dq[0]])
    return out

