import random

def reservoir_sample(iterable, k, seed=7):
    rng = random.Random(seed)
    sample = []
    for i, item in enumerate(iterable):
        if i < k:
            sample.append(item)
        else:
            j = rng.randint(0, i)
            if j < k:
                sample[j] = item
    return sample

print(reservoir_sample(range(100), 5))
